package com.andye.warmod.radar.client.gui;import com.andye.warmod.radar.client.ClientRadarTrack;import net.minecraft.client.gui.Font;import net.minecraft.client.gui.GuiGraphicsExtractor;import net.minecraft.network.chat.Component;public final class RadarTooltip{private RadarTooltip(){}public static void render(GuiGraphicsExtractor g,Font f,ClientRadarTrack t,int x,int y){String text=t.snapshot().phase().label()+"  "+t.id().toString().substring(0,8);int w=f.width(text)+8;g.fill(x+8,y+8,x+8+w,y+24,0xee10171b);g.text(f,Component.literal(text),x+12,y+12,0xffffffff);}}
